  | { type: 'list'; format: 'ordered' | 'unordered'; children: BlockListItem[] };

export interface PriceFactorSeed {
  role: 'vehicleYear' | 'birthDate';
  operand: 'vehicleAge' | 'ageInYears';
  min: number | null;
  max: number | null;
  multiplier: number;
}

export interface CountryDataSeed {
  code: string;
  name: string;
  intlLocale: string;
  currency: string;
  minimumAge: number;
  wizardTexts: Record<string, string>;
  formStepTexts: Record<string, string>;
  plansStepTexts: Record<string, string>;
  summaryStepTexts: Record<string, string>;
  confirmationTexts: Record<string, string>;
  priceFactors: PriceFactorSeed[];
  termsAndConditions: Block[];
}

type ValidationRuleSeed =
  | { kind: 'minLength' | 'maxLength' | 'min' | 'max'; value: number }
  | { kind: 'pattern'; pattern: string }
  | { kind: 'integer' };

export interface FormFieldSeed {
  publish: boolean;
  key: string;
  label: string;
  type: 'text' | 'number' | 'select' | 'date' | 'checkbox';
  required: boolean;
  helpText?: string;
  errorMessage?: string;
  order?: number;
  section: 'policyholder' | 'vehicle';
  role?: 'documentNumber' | 'birthDate' | 'vehicleYear';
  options?: { value: string; label: string }[];
  validations?: ValidationRuleSeed[];
}

export interface PlanSeed {
  publish: boolean;
  name: string;
  shortDescription?: string;
  basePrice: number;
  currency: string;
  order?: number;
  recommended: boolean;
  active: boolean;
  coverages: { label: string }[];
  benefits: { label: string }[];
}

export interface CountrySeed {
  country: CountryDataSeed;
  formFields: FormFieldSeed[];
  plans: PlanSeed[];
}

export interface CountrySelectionSeed {
  heading: string;
  intro: string;
  countryListLabel: string;
}

// ---------- Implementation ----------

const COUNTRY = 'api::country.country';
const FORM_FIELD = 'api::form-field.form-field';
const PLAN = 'api::plan.plan';
const COUNTRY_SELECTION = 'api::country-selection.country-selection';

interface Counters {
  created: number;
  existing: number;
}

const log = (strapi: Core.Strapi, message: string) => strapi.log.info(`[seed] ${message}`);

async function seedCountry(strapi: Core.Strapi, seed: CountrySeed, counters: Counters) {
  const countries = strapi.documents(COUNTRY);
  const { code } = seed.country;

  let country = await countries.findFirst({ filters: { code } });
  if (country) {
    counters.existing += 1;
    log(strapi, `country ${code}: exists (documentId ${country.documentId}), not modified`);
  } else {
    country = await countries.create({ data: seed.country });
    await countries.publish({ documentId: country.documentId });
    counters.created += 1;
    log(strapi, `country ${code}: created and published (documentId ${country.documentId})`);
  }

  const fields = strapi.documents(FORM_FIELD);
  for (const { publish, ...field } of seed.formFields) {
    const found = await fields.findFirst({ filters: { key: field.key } });
    if (found) {
      counters.existing += 1;
      continue;
    }
    const created = await fields.create({ data: { ...field, country: country.documentId } });
    if (publish) {
      await fields.publish({ documentId: created.documentId });
    }
    counters.created += 1;
    log(strapi, `form-field ${field.key}: created (${publish ? 'published' : 'draft only'})`);
  }

  const plans = strapi.documents(PLAN);
  for (const { publish, ...plan } of seed.plans) {
    const found = await plans.findFirst({ filters: { name: plan.name, country: { code } } });
    if (found) {
      counters.existing += 1;
      continue;
    }
    const created = await plans.create({ data: { ...plan, country: country.documentId } });
    if (publish) {
      await plans.publish({ documentId: created.documentId });
    }
    counters.created += 1;
    log(
      strapi,
      `plan ${code}/"${plan.name}": created (${publish ? 'published' : 'draft only'}, active=${plan.active})`,
    );
  }
}

async function seedCountrySelection(strapi: Core.Strapi, counters: Counters) {
  const selection = strapi.documents(COUNTRY_SELECTION);
  const found = await selection.findFirst();
  if (found) {
    counters.existing += 1;
    log(strapi, 'country-selection: exists, not modified');
    return;
  }
  const created = await selection.create({ data: countrySelection });
  await selection.publish({ documentId: created.documentId });
  counters.created += 1;
  log(strapi, 'country-selection: created and published');
}

export async function runSeed(strapi: Core.Strapi): Promise<void> {
  const counters: Counters = { created: 0, existing: 0 };
  for (const seed of [co, cl]) {
    await seedCountry(strapi, seed, counters);
  }
  await seedCountrySelection(strapi, counters);
  log(strapi, `done: ${counters.created} created, ${counters.existing} already present (left untouched)`);
}

/**
 * Public role permissions (content-model section 4, ADR-0003 section 1, D4 refined by G3-2).
 *
 * Applied on every bootstrap, idempotently: after it runs the public role has EXACTLY the
 * permissions below and nothing else; the authenticated role has none; sign-ups are disabled.
 * Any permission added by hand in the admin is revoked on the next start (by design).
 *
 * Only `find`, no `findOne`: no read in api-contracts needs it (the chosen plan is checked
 * against the list, REQ-03.14). No upload, users-permissions (auth/user/role) or i18n permissions.
 */
import type { Core } from '@strapi/strapi';

export const PUBLIC_PERMISSIONS: ReadonlyArray<{ action: string; reason: string }> = [
  {
    action: 'api::country.country.find',
    reason: 'Country list, country config, price factors and terms (api-contracts C1, C3, C6, C7)',
  },
  { action: 'api::form-field.form-field.find', reason: 'Step 1 fields of the country (C4)' },
  { action: 'api::plan.plan.find', reason: 'Plans of the country for step 2 and summary (C5)' },
  { action: 'api::country-selection.country-selection.find', reason: 'Texts of the / page (C2)' },
];

const ROLE = 'plugin::users-permissions.role';
const PERMISSION = 'plugin::users-permissions.permission';

const log = (strapi: Core.Strapi, message: string) => strapi.log.info(`[permissions] ${message}`);

async function findRole(strapi: Core.Strapi, type: 'public' | 'authenticated') {
  const role = await strapi.db.query(ROLE).findOne({ where: { type } });
  if (!role) {
    throw new Error(`[permissions] users-permissions role "${type}" not found`);
  }
  return role as { id: number };
}

async function permissionsOf(strapi: Core.Strapi, roleId: number) {
  return (await strapi.db.query(PERMISSION).findMany({ where: { role: { id: roleId } } })) as Array<{
    id: number;
    action: string;
  }>;
}

export async function applyPublicPermissions(strapi: Core.Strapi): Promise<void> {
  const allowed = new Set(PUBLIC_PERMISSIONS.map((p) => p.action));

  // Public role: grant the allowlist, revoke everything else.
  const publicRole = await findRole(strapi, 'public');
  const current = await permissionsOf(strapi, publicRole.id);
  const revoked: string[] = [];
  const kept = new Set<string>();
  for (const permission of current) {
    if (allowed.has(permission.action) && !kept.has(permission.action)) {
      kept.add(permission.action);
    } else {
      await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
      revoked.push(permission.action);
    }
  }
  const granted: string[] = [];
  for (const action of allowed) {
    if (!kept.has(action)) {
      await strapi.db.query(PERMISSION).create({ data: { action, role: publicRole.id } });
      granted.push(action);
    }
  }

  // Authenticated role: no permissions (content-model section 4).
  const authenticatedRole = await findRole(strapi, 'authenticated');
  const authenticatedRevoked: string[] = [];
  for (const permission of await permissionsOf(strapi, authenticatedRole.id)) {
    await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
    authenticatedRevoked.push(permission.action);
  }

  // "Enable sign-ups" = false (ADR-0003 section 1).
  const store = strapi.store({ type: 'plugin', name: 'users-permissions' });
  const advanced = ((await store.get({ key: 'advanced' })) ?? {}) as Record<string, unknown>;
  if (advanced.allow_register !== false) {
    await store.set({ key: 'advanced', value: { ...advanced, allow_register: false } });
    log(strapi, 'sign-ups disabled (allow_register=false)');
  }

  log(strapi, `public: granted [${granted.join(', ')}], revoked [${revoked.join(', ')}]`);
  log(strapi, `authenticated: revoked [${authenticatedRevoked.join(', ')}]`);
  const final = (await permissionsOf(strapi, publicRole.id)).map((p) => p.action).sort();
  log(strapi, `public role now has exactly: [${final.join(', ')}]`);
}

import type { Core } from '@strapi/strapi';
import { applyPublicPermissions } from './seed/permissions';
import { runSeed } from './seed/seed';

export default {
  register(/* { strapi }: { strapi: Core.Strapi } */) {},

  /**
   * Runs after the plugins' bootstrap on every start. Both steps are idempotent
   * (content-model sections 4 and 6, ADR-0003 section 1). A failure stops Strapi on purpose:
   * the stack must not serve content with unexpected permissions or a partial seed.
   */
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await applyPublicPermissions(strapi);
    await runSeed(strapi);
  },
};

