cat > "$N/snippets/security-headers.conf" <<'EOF'
# Security headers (ADR-0003 section 2). add_header is only inherited when the current
# level defines none, so this file is included in EVERY location that sets add_header.
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'" always;
EOF
cat > "$N/snippets/strapi-api.conf" <<'EOF'
# Read-only proxy to the Strapi Content API (ADR-0003 section 2, D4).
# Included ONLY from the exact-match allowlist locations of default.conf.

# GET (and therefore HEAD) only; any other method gets 403.
limit_except GET {
    deny all;
}

# Best-effort rejection of draft reads. $args is the raw query, so an encoded key
# (%73tatus) bypasses it: the real guarantee is the published-only middleware in Strapi.
if ($args ~* "(^|&)(status|publicationFilter)(=|%5B|\[)") {
    return 400;
}

proxy_pass http://strapi;
proxy_http_version 1.1;
proxy_set_header Connection "";
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;

# Never forward credentials, even if the browser sent them.
proxy_set_header Authorization "";
proxy_set_header Cookie "";

# GET has no body: never forward one.
proxy_pass_request_body off;
proxy_set_header Content-Length "";

proxy_connect_timeout 5s;
proxy_read_timeout 15s;

# No HTTP cache anywhere: every reload asks Strapi (Q-01.20, REQ-01.6, REQ-02.23).
proxy_hide_header Cache-Control;
proxy_hide_header Expires;
proxy_hide_header Set-Cookie;
proxy_hide_header X-Powered-By;
proxy_hide_header Content-Security-Policy;
add_header Cache-Control "no-store" always;
include /etc/nginx/snippets/security-headers.conf;
EOF
cat > "$N/default.conf" <<'EOF'
# nginx: single entry point of the browser (ADR-0003 section 2, D4).
#   - Serves the Angular production build (SPA fallback to index.html).
#   - Proxies an EXACT allowlist of Strapi Content API paths, GET/HEAD only.
#   - Everything else under /api is 404 (findOne, /api/auth/*, /api/upload, /api/users...).
# The Strapi admin does NOT go through nginx (it is published only on 127.0.0.1:1337).

upstream strapi {
    server cms:1337;
    keepalive 8;
}

server {
    listen 80;
    listen [::]:80;
    server_name _;
    server_tokens off;

    root /usr/share/nginx/html;
    index index.html;

    client_max_body_size 16k;

    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types application/json application/javascript text/css text/plain image/svg+xml;

    # ---------- Content API allowlist (api-contracts section 1) ----------
    location = /api/countries {
        include /etc/nginx/snippets/strapi-api.conf;
    }

    location = /api/form-fields {
        include /etc/nginx/snippets/strapi-api.conf;
    }

    location = /api/plans {
        include /etc/nginx/snippets/strapi-api.conf;
    }

    location = /api/country-selection {
        include /etc/nginx/snippets/strapi-api.conf;
    }

    # Anything else under /api is not exposed.
    location = /api {
        add_header Cache-Control "no-store" always;
        include /etc/nginx/snippets/security-headers.conf;
        return 404;
    }

    location /api/ {
        add_header Cache-Control "no-store" always;
        include /etc/nginx/snippets/security-headers.conf;
        return 404;
    }

    # ---------- SPA ----------
    # Bundles with a content hash from `ng build` (name-XXXXXXXX.ext): cache forever.
    location ~* "^/(?:.+/)?[^/]+-[A-Z0-9]{8}\.(?:js|mjs|css|woff2?|ttf|otf|png|jpe?g|gif|svg|webp|avif|ico)$" {
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        include /etc/nginx/snippets/security-headers.conf;
    }

    # index.html is always revalidated so a new build is picked up.
    location = /index.html {
        add_header Cache-Control "no-cache" always;
        include /etc/nginx/snippets/security-headers.conf;
    }

    # Client-side routes (/co, /cl/plans, ...) fall back to index.html.
    location / {
        try_files $uri /index.html;
        include /etc/nginx/snippets/security-headers.conf;
    }
}
EOF
cat > "$N/Dockerfile" <<'EOF'
# Web image: compiles frontend/ with `ng build` and serves it with nginx (ADR-0003, ADR-0007 E1).
# Build context: repository root (docker-compose.yml: context ".", dockerfile infra/nginx/Dockerfile).
# Ignore rules: infra/nginx/Dockerfile.dockerignore (host node_modules never enter the image).

# ---------- build: Angular production build ----------
FROM node:24.22.3-trixie-slim AS build
WORKDIR /app
ENV NG_CLI_ANALYTICS=false
COPY frontend/package.json frontend/package-lock.json ./
RUN npm ci --no-audit --no-fund
COPY frontend/ ./
RUN npx ng build --configuration production

# ---------- runtime: nginx ----------
FROM nginx:1.30-alpine AS runtime
COPY infra/nginx/default.conf /etc/nginx/conf.d/default.conf
COPY infra/nginx/snippets/ /etc/nginx/snippets/
# @angular/build:application writes the browser bundle to dist/<project>/browser.
COPY --from=build /app/dist/car-insurance-quote/browser/ /usr/share/nginx/html/
RUN nginx -t
EXPOSE 80
EOF
cat > "$N/Dockerfile.dockerignore" <<'EOF'
# Build context is the repository root: send only what the web image needs.
*
!frontend/
frontend/node_modules
frontend/dist
frontend/.angular
frontend/coverage
!infra/nginx/default.conf
!infra/nginx/snippets/
EOF
find "$N" -type f

