# F-00.12: the location is chosen on the NORMALISED URI ($uri: %XX decoded, `..` and `//`
# resolved), so `/api/users/..%2Fplans` or `/content-manager/...%2F..%2Fapi%2Fplans` land here.
#  (b) Reject any request whose ORIGINAL path is not literally an allowlisted path.
if ($request_uri !~ "^/api/(countries|form-fields|plans|country-selection)(\?|$)") {
    return 404;
}

#  (a) Forward only the normalised path that matched the exact location, never the original
#      URI. `strapi` is an upstream block, so a variable in proxy_pass needs no resolver.
proxy_pass http://strapi$uri$is_args$args;
proxy_http_version 1.1;

