# ---------- SPA ----------
# Bundles with a content hash from `ng build` (name-XXXXXXXX.ext; esbuild hashes may contain
# `_` and `-`, F-00.13): cache forever.
location ~* "^/(?:.+/)?[^/]+-[A-Za-z0-9_-]{8}\.(?:js|mjs|css|woff2?|ttf|otf|png|jpe?g|gif|svg|webp|avif|ico)$" {
    try_files $uri =404;
    add_header Cache-Control "public, max-age=31536000, immutable" always;
    include /etc/nginx/snippets/security-headers.conf;

